// Package config validates the safe subset of previewdock.yml consumed by the controller.
package config
import("fmt";"net/url";"strings";"time")
type Config struct{Version int; Build Build; Service Service; Health Health; Resources Resources; Preview Preview}
type Build struct{Context,Dockerfile string};type Service struct{ContainerPort int};type Health struct{Path string;ExpectedStatus int};type Resources struct{CPU float64;MemoryMB int};type Preview struct{TTL time.Duration;Authentication string}
func (c Config) Validate()error{if c.Version!=1{return fmt.Errorf("unsupported config version")};if c.Build.Context==""||strings.HasPrefix(c.Build.Context,"/")||strings.Contains(c.Build.Context,"..") {return fmt.Errorf("unsafe build context")};if c.Build.Dockerfile==""||strings.HasPrefix(c.Build.Dockerfile,"/")||strings.Contains(c.Build.Dockerfile,"..") {return fmt.Errorf("unsafe dockerfile path")};if c.Service.ContainerPort<1||c.Service.ContainerPort>65535{return fmt.Errorf("invalid container port")};if !strings.HasPrefix(c.Health.Path,"/")||strings.Contains(c.Health.Path,"//"){return fmt.Errorf("invalid health path")};if _,err:=url.ParseRequestURI(c.Health.Path);err!=nil{return fmt.Errorf("invalid health path")};if c.Health.ExpectedStatus<100||c.Health.ExpectedStatus>599{return fmt.Errorf("invalid health status")};if c.Resources.CPU<=0||c.Resources.CPU>32||c.Resources.MemoryMB<64{return fmt.Errorf("invalid resource limits")};if c.Preview.TTL<time.Hour||c.Preview.TTL>30*24*time.Hour{return fmt.Errorf("preview ttl must be between 1h and 30d")};if c.Preview.Authentication!="required"&&c.Preview.Authentication!="public"&&c.Preview.Authentication!="password"{return fmt.Errorf("invalid preview authentication")};return nil}
